/*
a = p
                    c = a(t)p(2t)
                    where 
                    p ∈ ℝ -> ℝ
                    t ∈ ℝ 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    std::function<DT(DT)> a;
    DT c;

    heartlib(
        const std::function<double(double)> & p,
        const double & t)
    {

        // a = p
        a = p;
        // c = a(t)p(2t)
        c = a(t) * p(2 * t);
    }
};

